<?php declare(strict_types=1);use App\Helpers\View;$e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');ob_start();?><?php if(!empty($noticeBtp)): ?><p role="status"><?= $e($noticeBtp) ?></p><?php unset($_SESSION['btp_budget_notice']);endif; ?><div class="btp-shell btp-workspace"><nav class="btp-breadcrumb"><a href="<?= $e(View::url('btp/dashboard')) ?>">BTP</a><span>/</span><strong>Déboursés</strong></nav><header class="btp-banner"><small>COÛTS PRÉVISIONNELS</small><h1><i class="fa-solid fa-coins"></i> Déboursés prévisionnels</h1><p>Historique des révisions budgétaires établies à partir des bons de commande.</p></header><p><a class="btp-primary-link" href="<?= $e(View::url('btp/debourses/nouveau')) ?>">+ Nouveau déboursé</a></p><div class="btp-chantier-card-grid"><?php foreach($budgetsBtp as $b): ?><article class="btp-chantier-card"><strong><?= $e($b['order_reference']) ?> · Révision <?= (int)$b['revision'] ?></strong><h3><?= $e($b['intitule']) ?></h3><p><?= $e($b['client_nom']) ?></p><p>Coût prévisionnel : <strong><?= number_format((float)$b['total_cost'],2,',',' ') ?> FCFA</strong></p><p>Marge prévisionnelle : <strong><?= number_format((float)$b['expected_margin'],2,',',' ') ?> FCFA</strong></p><span class="btp-chantier-status"><?= $e($b['status']) ?></span><?php if($b['status']==='brouillon'&&$canValidateBudgetBtp): ?><form method="post" action="<?= $e(View::url('btp/debourses/'.(int)$b['id'].'/valider')) ?>"><input type="hidden" name="_csrf" value="<?= $e($csrfBtp) ?>"><button type="submit">Valider le déboursé</button></form><?php endif; ?></article><?php endforeach; ?></div><?php if(!$budgetsBtp): ?><section class="btp-panel"><p>Aucun déboursé enregistré.</p></section><?php endif; ?></div><?php $content=ob_get_clean();require BASE_PATH.'/views/layouts/module.php';